// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame, ERC20Interface} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;

    function setUp() public { c = new PoCGame(address(this), 1000000000000000000); }

    // fuzz the tokenOwner and tokens to let fuzzer search inputs; tokenAddress will be our recorder deployed inside
    function testFuzz_property(address tokenOwner, uint256 tokens) public {
        // wide assumptions to keep addresses in normal range (not zero address for owner to avoid degenerate cases)
        vm.assume(tokenOwner != address(0));
        // deploy a recording token that implements transfer and records invocations
        RecorderToken recorder = new RecorderToken();

        // ensure c's caller is the owner (setUp used msg.sender as deployer/owner which is this test contract)
        // call transferAnyERC20Token as owner
        (bool ok, ) = address(c).call(abi.encodeWithSignature("transferAnyERC20Token(address,address,uint256)", address(recorder), tokenOwner, tokens));

        // The reference contract should have actually called recorder.transfer, so recorder.callCount() == 1.
        // The mutant returns early and does not call recorder, so recorder.callCount() == 0 for that mutant on SOME inputs.
        // We assert that recorder.callCount() == 1 (a property the reference satisfies for ALL inputs) — the mutant will fail for some inputs.
        uint256 recorded = recorder.callCount();
        assertTrue(recorded == 1);
    }
}

// Recorder token that mimics an ERC20 and records transfer invocations
contract RecorderToken is ERC20Interface {
    uint256 public callCount = 0;
    address public lastTo;
    uint256 public lastTokens;
    address public lastCaller;

    // match the ERC20 transfer signature exactly
    function transfer(address to, uint256 tokens) public override returns (bool success) {
        callCount += 1;
        lastTo = to;
        lastTokens = tokens;
        lastCaller = msg.sender;
        return true;
    }

    // helper getters autogenerated for public vars suffice
}
